// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz parameters: from actor address, an array length selector (as uint8), and a value v
    // We fuzz an address `from`, the number of recipients `n` (as uint8) and the amount v.
    // The test deploys a Reverter helper which will ALWAYS revert when transferFrom is called.
    // General rule: when _tos is non-empty and the callee reverts, c.transfer should revert for ALL inputs.
    // The mutant that ignores the success flag will NOT revert for those inputs.
    function testFuzz_property(address from, uint8 n, uint256 v) public {
        // keep number of recipients reasonable but allow 1..10 to let fuzzer find small sizes
        uint256 len = bound(n, 1, 10);

        // build recipients array
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // use distinct but deterministic addresses derived from `from` to keep domain wide
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i)))));
        }

        // deploy a helper that will revert when called with the selector transferFrom(address,address,uint256)
        Reverter reverter = new Reverter();

        // call c.transfer and observe whether it reverts. The REFERENCE must revert for ALL inputs here.
        bool ok;
        try c.transfer(from, address(reverter), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert the universal property: call must revert (ok == false).
        // This holds for the correct contract which checks success; the mutant that ignores success will make ok == true for some inputs.
        assertTrue(!ok);
    }
}

// Adversarial helper: when c calls transferFrom(...) this contract reverts, exposing the difference
contract Reverter {
    // declare the exact function signature so ABI dispatch matches (transferFrom(address,address,uint256))
    function transferFrom(address, address, uint256) external pure {
        revert("revert from callee");
    }
    // also include fallback to be safe
    fallback() external payable {
        revert("revert fallback");
    }
}
